from django.http import HttpResponse
from django.urls import include, path

def child_status_view(request):
    return HttpResponse("ok")

child_patterns = [path("status/", child_status_view, name="status")]
urlpatterns = [path("api/", include((child_patterns, "child")))]

class Resource:
    def __init__(self, identifier):
        self.identifier = identifier

    def detail_url(self):
        return f"/resources/{self.identifier}/"

def register(method, pattern, callback):
    return {"method": method, "pattern": pattern, "callback": callback}

def status_callback():
    return {"status": "ok"}

registrations = [register("GET", "/status", status_callback)]
